# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    chosen = []
    for job in sorted(payload, key=lambda item: (-item['profit'], item['id'])):
        if job['profit'] > 0 and all(job['end'] <= old['start'] or old['end'] <= job['start'] for old in chosen):
            chosen.append(job)
    chosen.sort(key=lambda item: (item['start'], item['end'], item['id']))
    return {'profit': sum(job['profit'] for job in chosen), 'jobs': [job['id'] for job in chosen]}

